from pathlib import Path
import argparse,json,hashlib,os
ap=argparse.ArgumentParser();ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();assert not a.output.exists();out=a.output.with_name(a.output.name+'.pending');out.mkdir();sources=out/'source-root/ShielddSecurity';sources.mkdir(parents=True);inventory={}
def emit(n,imports,body,names):
 s='-- GENERATED by generate.py. Do not hand edit.\n'+''.join('import ShielddSecurity.'+i+'\n' for i in sorted(set(imports)))+'set_option autoImplicit false\nset_option maxHeartbeats 900000\nset_option maxRecDepth 8192\nnoncomputable section\nnamespace ShielddSecurity.'+n+'\nopen FixedWindowJoin488\n'+body+'\nend ShielddSecurity.'+n+'\n'
 ns=['ShielddSecurity.'+n+'.'+x for x in names]
 for name in ns:s+='\nset_option pp.all true in\n#check @'+name+'\n#print axioms '+name+'\n'
 p=sources/(n+'.lean');p.write_text(s);inventory[n]=dict(sha256=hashlib.sha256(p.read_bytes()).hexdigest(),audits=ns)
leaves=[];sizes={};starts={}
for batch,start in enumerate(range(1,126,4)):
 ids=list(range(start,min(start+4,126)));n='AuthorizationFixedSchedule489B'+str(batch).zfill(2);leaves.append(n);sizes[n]=len(ids);starts[n]=start;imports=['FixedWindowMeaning491','FixedWindowWiring495'];entries=[]
 for i in ids:
  op='AuthorizationFixedCapture479B'+str((i-1)//2).zfill(3);sel='AuthorizationFixedSelectors481B'+str(i//2).zfill(3);imports += [op,sel];entries.append('⟨'+str(i)+','+op+'.entries['+str((i-1)%2)+'],('+sel+'.tables['+str(i%2)+']).1⟩')
 body='def entries : List Entry := ['+','.join(entries)+']\n'
 body+='theorem checked : entries.all check=true := by\n'
 for i,value in zip(ids,entries):
  op='AuthorizationFixedCapture479B'+str((i-1)//2).zfill(3);sel='AuthorizationFixedSelectors481B'+str(i//2).zfill(3)
  body+='  have h'+str(i)+' : check '+value+'=true := FixedWindowWiring495.checked '+value+'\n'
  body+='    (List.all_eq_true.mp '+op+'.checked ('+op+'.entries['+str((i-1)%2)+']) (List.getElem_mem (by decide)))\n'
  body+='    (List.all_eq_true.mp '+sel+'.checked ('+sel+'.entries['+str(i%2)+']) (List.getElem_mem (by decide)))\n'
  body+='    (by decide +kernel)\n'
 body+='  simp only [entries,List.all_cons,List.all_nil,'+','.join('h'+str(i) for i in ids)+',Bool.true_and]\n'
 body+='theorem meanings_checked : entries.all FixedWindowMeaning491.check=true := by decide +kernel\n'
 body+='theorem count : entries.length='+str(len(ids))+' := rfl\n'
 body+='theorem schedule : entries.map (fun e => e.index)='+str(ids).replace(' ','')+' := rfl\n'
 emit(n,imports,body,['entries','checked','meanings_checked','count','schedule'])
groups=[]
for batch,start in enumerate(range(0,len(leaves),8)):
 ns=leaves[start:start+8];n='AuthorizationFixedSchedule489G'+str(batch).zfill(2);groups.append(n);sizes[n]=sum(sizes[x] for x in ns);starts[n]=starts[ns[0]]
 body='def entries : List Entry := '+'++'.join(x+'.entries' for x in ns)+'\n'
 body+='theorem checked : entries.all check=true := by\n  simp only [entries,List.all_append,'+','.join(x+'.checked' for x in ns)+',Bool.true_and]\n'
 body+='theorem meanings_checked : entries.all FixedWindowMeaning491.check=true := by\n  simp only [entries,List.all_append,'+','.join(x+'.meanings_checked' for x in ns)+',Bool.true_and]\n'
 body+='theorem count : entries.length='+str(sizes[n])+' := by\n  simp only [entries,List.length_append,'+','.join(x+'.count' for x in ns)+']\n'
 body+='theorem schedule : entries.map (fun e => e.index)='+str(list(range(starts[n],starts[n]+sizes[n]))).replace(' ','')+' := by\n  simp only [entries,List.map_append,'+','.join(x+'.schedule' for x in ns)+']\n  rfl\n'
 emit(n,ns,body,['entries','checked','meanings_checked','count','schedule'])
body='def entries : List Entry := '+'++'.join(x+'.entries' for x in groups)+'\n'
body+='theorem checked : entries.all check=true := by\n  simp only [entries,List.all_append,'+','.join(x+'.checked' for x in groups)+',Bool.true_and]\n'
body+='theorem meanings_checked : entries.all FixedWindowMeaning491.check=true := by\n  simp only [entries,List.all_append,'+','.join(x+'.meanings_checked' for x in groups)+',Bool.true_and]\n'
body+='theorem count : entries.length=125 := by\n  simp only [entries,List.length_append,'+','.join(x+'.count' for x in groups)+']\n'
body+='theorem schedule : entries.map (fun e => e.index)=List.range\' 1 125 := by\n  simp only [entries,List.map_append,'+','.join(x+'.schedule' for x in groups)+']\n  rfl\n'
emit('AuthorizationFixedSchedule489',groups,body,['entries','checked','meanings_checked','count','schedule'])
(out/'generation.json').write_text(json.dumps(inventory,indent=2,sort_keys=True)+'\n');os.replace(out,a.output);print(json.dumps(dict(modules=len(inventory),windows=125)))
